onDateSelected:
{{
  Get_Calendar_Events_Machine.run().then(() => {
    const resas = Get_Calendar_Events_Machine.data || [];
    const dateChoisie = moment(dat_loc_debut.selectedDate).format("YYYY-MM-DD");
    const dureeChoisie = sel_loc_duree.selectedOptionValue;

    const resasDuJour = resas.filter(r => moment(r.Date_Location).format("YYYY-MM-DD") === dateChoisie);
    const aMatin = resasDuJour.some(r => ['Matin', 'Journee', 'Multi_Jours', 'Journee_Demi'].includes(r.Type_Duree));
    const aAprem = resasDuJour.some(r => ['Apres_Midi', 'Journee', 'Multi_Jours', 'Journee_Demi'].includes(r.Type_Duree));

    let estOccupe = false;
    if ((dureeChoisie === 'Journee' || dureeChoisie === 'Multi_Jours') && resasDuJour.length > 0) estOccupe = true;
    if (dureeChoisie === 'Matin' && aMatin) estOccupe = true;
    if (dureeChoisie === 'Apres_Midi' && aAprem) estOccupe = true;

    if (estOccupe) {
      showAlert('⚠️ Ce créneau est déjà réservé pour ce matériel !', 'warning');
    }
  });
}}
